package handlers

import (
	"context"
	"encoding/json"
	"net/http"

	"github.com/gin-gonic/gin"
	"github.com/yourusername/yourproject/db"
)

func GetGroceries(c *gin.Context) {
	var groc []db.Grocery
	if err := db.GetGroceries(c.DB(), &groc); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, groc)
}

func GetGrocery(c *gin.Context) {
	var id uint
	if err := json.Unmarshal([]byte(c.Request.Body()), &id); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	var g *db.Grocery
	if g, err = db.GetGrocery(c.DB(), id); err != nil {
	 c.JSON(http.StatusNotFound, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, g)
}

func CreateGrocery(c *gin.Context) {
	var requestBody struct {
		Name     string `json:"name"`
		Quantity int    `json:"quantity"`
	}

	if err := json.Unmarshal(c.Request.Body(), &requestBody); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	g, err := db.CreateGrocery(c.DB(), requestBody.Name, requestBody.Quantity)
 if err != nil {
 c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusCreated, g)
}

func UpdateGrocery(c *gin.Context) {
	var requestBody struct {
		ID       uint   `json:"id"`
		Name     string `json:"name"`
		Quantity int    `json:"quantity"`
	}

	if err := json.Unmarshal(c.Request.Body(), &requestBody); err != nil {
	 c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	g, err := db.UpdateGrocery(c.DB(), requestBody.ID, requestBody.Name, requestBody.Quantity)
 if err != nil {
	 c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, g)
}

func DeleteGrocery(c *gin.Context) {
	var id uint
	if err := json.Unmarshal([]byte(c.Request.Body()), &id); err != nil {
	 c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
 if err := db.DeleteGrocery(c.DB(), id); err != nil {
	 c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, gin.H{"message": "Grocery deleted"})
}

